CREATE OR REPLACE FUNCTION public.rpc_bi_visitas_por_consultor(p_consultor_id uuid, p_data_inicio date DEFAULT NULL, p_data_fim date DEFAULT NULL) RETURNS SETOF public.vw_fluxo_visita_tecnica LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Autenticação necessária'; END IF; RETURN QUERY SELECT * FROM public.vw_fluxo_visita_tecnica WHERE consultor_id = p_consultor_id AND (p_data_inicio IS NULL OR created_at >= p_data_inicio) AND (p_data_fim IS NULL OR created_at <= p_data_fim) ORDER BY created_at DESC; EXCEPTION WHEN OTHERS THEN RETURN; END; $$; GRANT EXECUTE ON FUNCTION public.rpc_bi_visitas_por_consultor(uuid, date, date) TO authenticated;

