CREATE OR REPLACE FUNCTION public.rpc_bi_esteira_por_microrganismo(p_microrganismo_id uuid, p_data_inicio date DEFAULT NULL, p_data_fim date DEFAULT NULL) RETURNS SETOF public.vw_esteira_laboratorio LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Autenticação necessária'; END IF; RETURN QUERY SELECT * FROM public.vw_esteira_laboratorio WHERE microrganismo_id = p_microrganismo_id AND (p_data_inicio IS NULL OR created_at >= p_data_inicio) AND (p_data_fim IS NULL OR created_at <= p_data_fim) ORDER BY created_at DESC; EXCEPTION WHEN OTHERS THEN RETURN; END; $$; GRANT EXECUTE ON FUNCTION public.rpc_bi_esteira_por_microrganismo(uuid, date, date) TO authenticated;

CREATE OR REPLACE VIEW public.vw_bi_estoque_produto AS SELECT ep.id, ep.produto_id, ep.microrganismo_id, COALESCE(p.nome, m.nome, 'Desconhecido') AS nome_produto, ep.volume_total AS volume_total_ml, COALESCE(ep.volume_total, 0) / 1000.0 AS volume_total_l, ep.updated_at FROM public.estoque_produto ep LEFT JOIN public.produtos p ON p.id = ep.produto_id LEFT JOIN public.microrganismos m ON m.id = ep.microrganismo_id; GRANT SELECT ON public.vw_bi_estoque_produto TO authenticated; GRANT ALL ON public.vw_bi_estoque_produto TO service_role;

CREATE OR REPLACE VIEW public.vw_bi_movimentacoes AS SELECT em.id, em.estoque_produto_id, em.acao AS tipo_movimentacao, em.quantidade AS volume_alteracao, em.observacao AS motivo, em.created_at, ep.produto_id, ep.microrganismo_id FROM public.estoque_movimentacoes em LEFT JOIN public.estoque_produto ep ON ep.id = em.estoque_produto_id; GRANT SELECT ON public.vw_bi_movimentacoes TO authenticated; GRANT ALL ON public.vw_bi_movimentacoes TO service_role;